begin;
with j as (select * from jsonb_to_recordset($law7d0016$[{"code_id":"APK_RF","article_number":"291.10","version_date":"2002-07-24","article_text":"1. Суд направляет лицам, участвующим в деле, копии определения о передаче кассационных жалобы, представления вместе с делом для рассмотрения в судебном заседании Судебной коллегии Верховного Суда Российской Федерации и копии кассационных жалобы, представления. Время рассмотрения кассационных жалобы, представления вместе с делом в судебном заседании Судебной коллегии Верховного Суда Российской Федерации назначается с учетом того, чтобы лица, участвующие в деле, имели возможность явиться в судебное заседание.\n\n2. Лица, участвующие в деле, извещаются о времени и месте рассмотрения Судебной коллегией Верховного Суда Российской Федерации кассационных жалобы, представления вместе с делом. Неявка надлежащим образом извещенных лиц не препятствует рассмотрению кассационных жалобы, представления.\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.10. Извещение лиц, участвующих в деле, о передаче кассационных жалобы, представления вместе с делом для рассмотрения в судебном заседании Судебной коллегии Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"48b9bee935dbf1fa9d0a8f528575c59ce6f0f5c03e795019e39cbc89e3567391"},{"code_id":"APK_RF","article_number":"291.11","version_date":"2002-07-24","article_text":"1. Основаниями для отмены или изменения Судебной коллегией Верховного Суда Российской Федерации судебных актов в порядке кассационного производства являются существенные нарушения норм материального права и (или) норм процессуального права, которые повлияли на исход дела и без устранения которых невозможны восстановление и защита нарушенных прав, свобод, законных интересов в сфере предпринимательской и иной экономической деятельности, а также защита охраняемых законом публичных интересов.\n\n2. Основанием для присуждения Судебной коллегией Верховного Суда Российской Федерации компенсации за нарушение права на судопроизводство в разумный срок является нарушение права на судопроизводство в разумный срок по причинам, не зависящим от лица, обратившегося с требованием о присуждении компенсации.\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.11. Основания для отмены или изменения Судебной коллегией Верховного Суда Российской Федерации судебных актов в порядке кассационного производства и присуждения компенсации за нарушение права на судопроизводство в разумный срок","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ef67428a123bde332bb90f7f60bde1f6435decf6c299343d2ba60f39d05e6c5a"},{"code_id":"APK_RF","article_number":"291.12","version_date":"2002-07-24","article_text":"1. Кассационные жалоба, представление вместе с делом рассматриваются в судебном заседании Судебной коллегии Верховного Суда Российской Федерации в срок, не превышающий двух месяцев со дня вынесения определения о передаче кассационных жалобы, представления вместе с делом для рассмотрения в судебном заседании Судебной коллегии Верховного Суда Российской Федерации.\n\n2. Рассматриваемые Судебной коллегией Верховного Суда Российской Федерации кассационные жалоба, представление вместе с делом докладываются судьей Верховного Суда Российской Федерации - докладчиком по данным жалобе, представлению.\n\n3. Судья-докладчик излагает обстоятельства дела, содержание судебных актов, принятых по делу, доводы, содержащиеся в кассационных жалобе, представлении, в том числе в кассационной жалобе, содержащей требование о присуждении компенсации за нарушение права на судопроизводство в разумный срок, и послужившие основанием для передачи кассационных жалобы, представления вместе с делом для рассмотрения в судебном заседании Судебной коллегии Верховного Суда Российской Федерации.\n\n4. В судебном заседании принимают участие лица, участвующие в деле, их представители, иные лица, подавшие кассационные жалобу, представление, если их права и законные интересы непосредственно затрагиваются обжалуемым судебным актом. Указанные лица могут участвовать в судебном заседании путем использования систем видеоконференц-связи в порядке, установленном статьей 1531 настоящего Кодекса.\n\n5. В случае, если прокурор является лицом, участвующим в рассмотрении дела, в судебном заседании Судебной коллегии Верховного Суда Российской Федерации по поручению Генерального прокурора Российской Федерации принимает участие должностное лицо органов прокуратуры.\n\n6. Лица, указанные в части 4 настоящей статьи и явившиеся в судебное заседание, вправе дать объяснения по делу. Первым дает объяснение лицо, подавшее кассационные жалобу, представление.\n\n7. Кассационная жалоба, содержащая требование о присуждении компенсации за нарушение права на судопроизводство в разумный срок, рассматривается по правилам, предусмотренным настоящей главой, и в соответствии с Федеральным законом от 30 апреля 2010 года № 68-ФЗ \"О компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок\".\n\n8. При решении вопроса о присуждении компенсации за нарушение права на судопроизводство в разумный срок Судебная коллегия Верховного Суда Российской Федерации в судебном заседании устанавливает факт нарушения права заявителя на судопроизводство в разумный срок, исходя из доводов, изложенных в кассационной жалобе, содержащей требование о присуждении указанной компенсации, содержания принятых по делу судебных актов, материалов дела и с учетом следующих обстоятельств:\n\n1) правовая и фактическая сложность дела;\n\n2) поведение заявителя и других участников арбитражного процесса;\n\n3) достаточность и эффективность действий суда или судьи, совершаемых в целях своевременного рассмотрения дела;\n\n4) общая продолжительность судопроизводства по делу.\n\n9. По результатам рассмотрения кассационных жалобы, представления вместе с делом Судебная коллегия Верховного Суда Российской Федерации выносит определение.\n\n10. Вопросы, возникающие при рассмотрении кассационных жалобы, представления вместе с делом в порядке кассационного производства, разрешаются судьями большинством голосов.\n\n11. По результатам рассмотрения кассационных жалобы, представления вместе с делом Судебная коллегия Верховного Суда Российской Федерации выносит определение и объявляет его по правилам, предусмотренным соответственно статьями 167 и 176 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.12. Срок и порядок рассмотрения кассационных жалобы, представления вместе с делом в судебном заседании Судебной коллегии Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c5fdaf20c1d5f725756894c50a82b6b58800584c1fbec8d4ce52fb371ac4edcd"},{"code_id":"APK_RF","article_number":"291.13","version_date":"2002-07-24","article_text":"1. В определении Судебной коллегии Верховного Суда Российской Федерации, вынесенном по результатам рассмотрения кассационных жалобы, представления в порядке кассационного производства, должны быть указаны:\n\n1) наименование и состав суда, вынесшего определение;\n\n2) номер дела, дата и место вынесения определения;\n\n3) наименование лица, подавшего кассационные жалобу, представление о пересмотре дела в порядке кассационного производства, его процессуальное положение, адрес или место жительства; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n4) фамилия и инициалы судьи, вынесшего определение о передаче кассационных жалобы, представления вместе с делом для рассмотрения в судебном заседании Судебной коллегии Верховного Суда Российской Федерации;\n\n5) содержание обжалуемых судебных актов;\n\n6) фамилии лиц, присутствовавших в судебном заседании, с указанием их полномочий;\n\n7) наименования арбитражных судов, рассмотревших дело в первой, апелляционной и кассационной инстанциях; дата принятия обжалуемых решения, постановления, определения; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n8) объяснения лиц, участвующих в деле и присутствовавших в судебном заседании;\n\n9) законы и иные нормативные правовые акты, которыми руководствовалась Судебная коллегия Верховного Суда Российской Федерации при вынесении определения; мотивы вынесенного определения; мотивы, по которым суд не применил законы и иные нормативные правовые акты, на которые ссылались лица, участвующие в деле;\n\n10) мотивы, по которым Судебная коллегия Верховного Суда Российской Федерации не согласилась с выводами суда первой, апелляционной или кассационной инстанции, если его решение, постановление или определение было отменено полностью или в части;\n\n11) выводы по результатам рассмотрения кассационных жалобы, представления;\n\n12) основания для присуждения компенсации за нарушение права на судопроизводство в разумный срок или отказа в ее присуждении;\n\n13) размер компенсации за нарушение права на судопроизводство в разумный срок;\n\n14) действия, которые должны быть выполнены лицами, участвующими в деле, и арбитражным судом первой, апелляционной или кассационной инстанции, если дело передается на новое рассмотрение.\n\n2. Копии определения Судебной коллегии Верховного Суда Российской Федерации, вынесенного по результатам рассмотрения кассационных жалобы, представления вместе с делом, направляются лицам, участвующим в деле, в пятидневный срок со дня вынесения определения.\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.13. Определение Судебной коллегии Верховного Суда Российской Федерации, вынесенное по результатам рассмотрения кассационных жалобы, представления","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2d82239a647e23f89d91ff66da78f8840edc00c2e4600b1e84877b26a716b3f3"},{"code_id":"APK_RF","article_number":"291.14","version_date":"2002-07-24","article_text":"1. Судебная коллегия Верховного Суда Российской Федерации по результатам рассмотрения кассационных жалобы, представления вместе с делом вправе:\n\n1) оставить решение суда первой инстанции, постановление или определение суда апелляционной или кассационной инстанции без изменения, кассационные жалобу, представление без удовлетворения;\n\n2) отменить решение суда первой инстанции, постановление или определение суда апелляционной или кассационной инстанции полностью либо в части и направить дело на новое рассмотрение в соответствующий арбитражный суд. При направлении дела на новое рассмотрение Судебная коллегия Верховного Суда Российской Федерации может указать на необходимость рассмотрения дела в ином составе судей;\n\n3) отменить решение суда первой инстанции, постановление или определение суда апелляционной или кассационной инстанции полностью либо в части и оставить заявление без рассмотрения или прекратить производство по делу;\n\n4) оставить в силе один из принятых по делу судебных актов;\n\n5) отменить либо изменить решение суда первой инстанции, постановление или определение суда апелляционной или кассационной инстанции и принять новый судебный акт, не передавая дело на новое рассмотрение, если допущена ошибка в применении и (или) толковании норм материального права;\n\n6) присудить компенсацию за нарушение права на судопроизводство в разумный срок или отказать в ее присуждении;\n\n7) оставить кассационные жалобу, представление без рассмотрения по существу при наличии оснований, предусмотренных статьей 2915 настоящего Кодекса.\n\n2. При рассмотрении дела в порядке кассационного производства Судебная коллегия Верховного Суда Российской Федерации проверяет правильность применения и (или) толкования норм материального права и (или) норм процессуального права арбитражными судами, рассматривавшими дело, в пределах доводов, изложенных в кассационных жалобе, представлении. В интересах законности Судебная коллегия Верховного Суда Российской Федерации вправе выйти за пределы доводов, изложенных в кассационных жалобе, представлении. При этом Судебная коллегия Верховного Суда Российской Федерации не вправе проверять законность судебных актов в той части, в которой они не обжалуются, а также законность судебных актов, которые не обжалуются.\n\n3. При рассмотрении дела в порядке кассационного производства Судебная коллегия Верховного Суда Российской Федерации не вправе устанавливать или считать доказанными обстоятельства, которые не были установлены либо были отвергнуты судом первой или апелляционной инстанции, либо предрешать вопросы о достоверности или недостоверности того или иного доказательства, преимуществе одних доказательств перед другими и определять, какой судебный акт должен быть принят при новом рассмотрении дела.\n\n4. Указания Судебной коллегии Верховного Суда Российской Федерации, в том числе на толкование закона, изложенные в определении об отмене судебного акта, обязательны для арбитражного суда, вновь рассматривающего дело.\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.14. Полномочия Судебной коллегии Верховного Суда Российской Федерации по результатам рассмотрения кассационных жалобы, представления вместе с делом","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"26b54f0c8a9796ddd4405fa36c6330d49fd8ce69cd75a051e1c3226ca66a8065"},{"code_id":"APK_RF","article_number":"291.15","version_date":"2002-07-24","article_text":"Определение Судебной коллегии Верховного Суда Российской Федерации, вынесенное по результатам рассмотрения кассационных жалобы, представления вместе с делом, вступает в законную силу со дня его вынесения.\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.15. Вступление в законную силу определения Судебной коллегии Верховного Суда Российской Федерации, вынесенного по результатам рассмотрения кассационных жалобы, представления вместе с делом","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"77ab39b9c8db83d7c919297a0a1cd19db3bf6a466b4a9cc6559f1796b9fe1a18"},{"code_id":"APK_RF","article_number":"291.16","version_date":"2002-07-24","article_text":"1. Кассационные жалобы, представления на судебные акты, принятые по делам, рассмотренным в порядке приказного производства, упрощенного производства, рассматриваются Судебной коллегией Верховного Суда Российской Федерации по правилам, предусмотренным настоящей главой, с учетом особенностей, установленных настоящей статьей.\n\n2. Кассационные жалобы, представления на судебные акты, принятые по делам, рассмотренным в порядке приказного производства, упрощенного производства, рассматриваются Судебной коллегией Верховного Суда Российской Федерации без вызова сторон. С учетом характера и сложности рассматриваемого вопроса, а также доводов кассационной жалобы и возражений относительно кассационной жалобы суд может вызвать лиц, участвующих в деле, в судебное заседание.\n\n(Дополнение статьей - Федеральный закон от 25.12.2023 № 667-ФЗ)\n\n(Глава утратила силу - Федеральный закон от 28.06.2014 № 186-ФЗ)\n\n(Дополнение главой - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.16. Особенности рассмотрения Судебной коллегией Верховного Суда Российской Федерации кассационных жалобы, представления на судебные акты, принятые по делам, рассмотренным в порядке приказного производства, упрощенного производства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2f8822872a785e7f5d54a9c23460b1278adf66b8096bf2020c7235e359f3680f"},{"code_id":"APK_RF","article_number":"291.2","version_date":"2002-07-24","article_text":"1. Кассационные жалоба, представление подаются в срок, не превышающий двух месяцев со дня вступления в силу последнего обжалуемого судебного акта, принятого по данному делу, если иное не предусмотрено настоящим Кодексом.\n\n2. Срок подачи кассационных жалобы, представления, пропущенный по причинам, не зависящим от лица, обратившегося с такими жалобой, представлением, в том числе в связи с отсутствием у него сведений об обжалуемом судебном акте, по ходатайству указанного лица может быть восстановлен судьей Судебной коллегии Верховного Суда Российской Федерации (далее - судья Верховного Суда Российской Федерации), рассматривающим кассационные жалобу, представление, при условии, что ходатайство подано не позднее шести месяцев со дня вступления в законную силу обжалуемого судебного акта или, если ходатайство подано одним из лиц, указанных в статье 42 настоящего Кодекса, со дня, когда это лицо узнало или должно было узнать о нарушении его прав и законных интересов обжалуемым судебным актом.\n\n3. Ходатайство о восстановлении пропущенного срока подачи кассационных жалобы, представления рассматривается судьей Верховного Суда Российской Федерации в порядке, предусмотренном статьей 117 настоящего Кодекса. По результатам рассмотрения данного ходатайства судья выносит определение о восстановлении пропущенного срока подачи кассационных жалобы, представления или об отказе в его восстановлении.\n\n4. Председатель Верховного Суда Российской Федерации, заместитель Председателя Верховного Суда Российской Федерации вправе не согласиться с определением судьи Верховного Суда Российской Федерации, указанным в части 3 настоящей статьи, и вынести определение об отказе в восстановлении пропущенного срока подачи кассационных жалобы, представления или о его восстановлении.\n\n5. До истечения срока, установленного настоящим Кодексом для подачи кассационных жалобы, представления, дело не может быть истребовано из арбитражного суда.\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.2. Срок подачи кассационных жалобы, представления","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9f0cc8ecc285abf02da2d6491725a613bd3f9b6d440c0b45c93e006ea716f3a2"},{"code_id":"APK_RF","article_number":"291.3","version_date":"2002-07-24","article_text":"1) наименование суда, в который подаются кассационные жалоба, представление;\n\n2) наименование лица, подающего кассационные жалобу, представление, его процессуальное положение;\n\n3) наименования лиц, участвующих в деле, их адрес или место жительства; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n4) сведения об обжалуемом судебном акте и наименование принявшего его арбитражного суда, сведения о других судебных актах, принятых по делу, предмет спора;\n\n5) основания, по которым лицо, подающее кассационные жалобу, представление, обжалует судебный акт, с указанием на то, в чем заключаются существенные нарушения норм материального права и (или) норм процессуального права, повлиявшие на исход судебного разбирательства, и приведением доводов, свидетельствующих о существенных нарушениях прав и законных интересов лица в сфере предпринимательской и иной экономической деятельности;\n\n6) законы или иные нормативные правовые акты, подтверждающие, по мнению лица, наличие нарушений, указанных в пункте 5 настоящей части;\n\n7) просьба лица, подающего кассационные жалобу, представление;\n\n8) перечень документов, прилагаемых к кассационным жалобе, представлению.\n\n1) общая продолжительность судопроизводства по делу, исчисляемая со дня поступления искового заявления или заявления в арбитражный суд первой инстанции до дня принятия последнего судебного акта по делу;\n\n2) обстоятельства, известные лицу, подавшему кассационную жалобу, и повлиявшие на длительность судопроизводства по делу;\n\n3) доводы лица, подавшего кассационную жалобу, с указанием оснований для присуждения компенсации и ее размера;\n\n4) последствия нарушения права на судопроизводство в разумный срок и их значимость для лица, подавшего кассационную жалобу;\n\n5) реквизиты банковского счета лица, подавшего кассационную жалобу, на который должны быть перечислены средства, подлежащие взысканию.\n\n1) копии обжалуемого судебного акта и других судебных актов, принятых по делу, которые должны быть заверены соответствующим судом только в случае рассмотрения дела в закрытом судебном заседании; (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)\n\n2) документы, подтверждающие уплату государственной пошлины в установленных порядке и размере или право на получение льготы по уплате государственной пошлины, либо ходатайство о предоставлении отсрочки, рассрочки уплаты государственной пошлины, об уменьшении ее размера;\n\n3) доверенность или иной документ, подтверждающие полномочия на подписание кассационных жалобы, представления, а также копии документов о высшем юридическом образовании или об ученой степени по юридической специальности представителя, подписавшего кассационную жалобу, либо документов, удостоверяющих его статус адвоката, патентного поверенного, арбитражного управляющего, единоличного органа управления организации. (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.3. Форма и содержание кассационных жалобы, представления","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a7f770f2570b53858f321a03e16586b604d565fa7fbd9e72414e5644ea0a0ce5"},{"code_id":"APK_RF","article_number":"291.4","version_date":"2002-07-24","article_text":"1. Лицо, участвующее в деле, получив копию кассационных жалобы, представления, направляет отзыв на кассационные жалобу, представление с приложением документов, подтверждающих возражения относительно жалобы, представления, другим лицам, участвующим в деле, и в Судебную коллегию Верховного Суда Российской Федерации.\n\n2. К отзыву, направляемому в Судебную коллегию Верховного Суда Российской Федерации, прилагается документ, подтверждающий направление отзыва другим лицам, участвующим в деле.\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.4. Отзыв на кассационные жалобу, представление","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0d6bca6ea4f9156d3694c1b6c4f4cc71939b6bd1a7fcc1e1d3d6e4f263767a0c"},{"code_id":"APK_RF","article_number":"291.5","version_date":"2002-07-24","article_text":"1. Кассационные жалоба, представление возвращаются без рассмотрения по существу, если:\n\n1) кассационные жалоба, представление не отвечают требованиям, установленным частью 1, пунктами 1 - 4, 7 части 2, частями 5 и 7 статьи 2913 настоящего Кодекса;\n\n2) кассационные жалоба, представление поданы лицом, не имеющим права на обжалование судебного акта в порядке кассационного производства, или поданы на судебный акт, который в соответствии с настоящим Кодексом не обжалуется в порядке кассационного производства;\n\n3) кассационные жалоба, представление поданы по истечении срока, установленного частями 1 и 2 статьи 2912 настоящего Кодекса, и не содержат ходатайство о его восстановлении или в восстановлении пропущенного срока отказано;\n\n4) поступило ходатайство о возвращении или об отзыве кассационных жалобы, представления;\n\n5) кассационные жалоба, представление поданы с нарушением правил подсудности, установленных частью 2 статьи 2911 настоящего Кодекса. (В редакции Федерального закона от 02.12.2019 № 406-ФЗ)\n\n2. Кассационные жалоба, представление должны быть возвращены без рассмотрения по существу в течение десяти дней со дня их поступления в суд кассационной инстанции.\n\n3. Возвращение кассационных жалобы, представления не препятствует повторному обращению с кассационными жалобой, представлением после устранения обстоятельств, послуживших основанием для их возвращения.\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.5. Возвращение кассационных жалобы, представления без рассмотрения по существу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"88d5444980c142741f4a239cee4331ad2ccec0cbcc88d3bf8e95cba45e192a52"},{"code_id":"APK_RF","article_number":"291.6","version_date":"2002-07-24","article_text":"1. Кассационные жалоба, представление, поданные в соответствии с правилами, установленными статьями 2911 - 2913 настоящего Кодекса, изучаются судьей Верховного Суда Российской Федерации.\n\n2. Судья Верховного Суда Российской Федерации изучает кассационные жалобу, представление по материалам, приложенным к ним, или по материалам истребованного дела.\n\nХодатайство о приостановлении исполнения судебных актов, подаваемое в электронном виде, должно быть подписано усиленной квалифицированной электронной подписью. (Дополнение абзацем - Федеральный закон от 23.06.2016 № 220-ФЗ) (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n1) об отказе в передаче кассационных жалобы, представления для рассмотрения в судебном заседании Судебной коллегии Верховного Суда Российской Федерации, если изложенные в кассационных жалобе, представлении доводы не подтверждают существенных нарушений норм материального права и (или) норм процессуального права, повлиявших на исход дела, и не являются достаточным основанием для пересмотра судебных актов в кассационном порядке и (или) для решения вопроса о присуждении компенсации за нарушение права на судопроизводство в разумный срок, а также если указанные доводы не находят подтверждения в материалах дела. При этом кассационные жалоба, представление, а также копии обжалуемых судебных актов остаются в суде кассационной инстанции;\n\n2) о передаче кассационных жалобы, представления вместе с делом для рассмотрения в судебном заседании Судебной коллегии Верховного Суда Российской Федерации.\n\nмене данного определения и передаче кассационных жалобы, представления для рассмотрения в судебном заседании суда кассационной инстанции. Время рассмотрения этих жалобы, представления в Верховном Суде Российской Федерации при исчислении указанного срока не учитывается. (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.6. Рассмотрение кассационных жалобы, представления в Судебной коллегии Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"92a719ea60b3867bb3ab455836e70b55531ee5fd3a924a1f40778885cb3488a9"},{"code_id":"APK_RF","article_number":"291.7","version_date":"2002-07-24","article_text":"1. Кассационные жалоба, представление рассматриваются в Верховном Суде Российской Федерации в срок, не превышающий двух месяцев, если дело не было истребовано, и в срок, не превышающий трех месяцев, если дело было истребовано, не считая времени со дня истребования дела до дня его поступления в Верховный Суд Российской Федерации.\n\n2. Председатель Верховного Суда Российской Федерации, заместитель Председателя Верховного Суда Российской Федерации в случае истребования дела с учетом его сложности могут продлить срок рассмотрения кассационных жалобы, представления, но не более чем на два месяца.\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.7. Срок рассмотрения кассационных жалобы, представления","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"211cb5e26a69e304bb76ff482b3d81659bfafb39c7356b3f63bdf133d567bace"},{"code_id":"APK_RF","article_number":"291.8","version_date":"2002-07-24","article_text":"В определении судьи Верховного Суда Российской Федерации об отказе в передаче кассационных жалобы, представления для рассмотрения в судебном заседании Судебной коллегии Верховного Суда Российской Федерации должны быть указаны:\n\n1) дата и место вынесения определения;\n\n2) фамилия и инициалы судьи, вынесшего определение;\n\n3) наименование лица, подавшего кассационные жалобу, представление, его процессуальное положение, адрес или место жительства; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n4) сведения об обжалуемом судебном акте, дата его принятия и вступления в законную силу;\n\n5) мотивы отказа в передаче кассационных жалобы, представления для рассмотрения в судебном заседании Судебной коллегии Верховного Суда Российской Федерации.\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.8. Определение об отказе в передаче кассационных жалобы, представления для рассмотрения в судебном заседании Судебной коллегии Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2d153f62ac9fb1663d93fad91ebe133bf37884a4fcf951a7775493306d5024bc"},{"code_id":"APK_RF","article_number":"291.9","version_date":"2002-07-24","article_text":"В определении судьи Верховного Суда Российской Федерации о передаче кассационных жалобы, представления вместе с делом для рассмотрения в судебном заседании Судебной коллегии Верховного Суда Российской Федерации должны быть указаны:\n\n1) дата и место вынесения определения;\n\n2) фамилия и инициалы судьи, вынесшего определение;\n\n3) наименование лица, подавшего кассационные жалобу, представление, его процессуальное положение, адрес или место жительства; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n4) сведения об обжалуемом судебном акте, дата его принятия и вступления в законную силу;\n\n5) содержание дела, по которому принят обжалуемый судебный акт;\n\n6) мотивированные основания передачи кассационных жалобы, представления вместе с делом для рассмотрения в судебном заседании Судебной коллегии Верховного Суда Российской Федерации и (или) для решения вопроса о присуждении компенсации за нарушение права на судопроизводство в разумный срок, а также общая продолжительность судопроизводства по делу.\n\n(Дополнение статьей - Федеральный закон от 28.06.2014 № 186-ФЗ)","article_title":"Статья 291.9. Определение о передаче кассационных жалобы, представления вместе с делом для рассмотрения в судебном заседании Судебной коллегии Верховного Суда Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c4ddf2f926635ae84210f1221be2b46a70b413e393cdef8b5be439b136ed2920"},{"code_id":"APK_RF","article_number":"3","version_date":"2002-07-24","article_text":"1. В соответствии с Конституцией Российской Федерации законодательство о судопроизводстве в арбитражных судах находится в ведении Российской Федерации.\n\n2. Порядок судопроизводства в арбитражных судах определяется Конституцией Российской Федерации, Федеральным конституционным законом \"О судебной системе Российской Федерации\" и Федеральным конституционным законом \"Об арбитражных судах в Российской Федерации\", Арбитражным процессуальным кодексом Российской Федерации (далее - Кодекс) и принимаемыми в соответствии с ними другими федеральными законами.","article_title":"Статья 3. Законодательство о судопроизводстве в арбитражных судах","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9b8263b9f1b5c905c1ff07b3209b4a64943987cf3d5db7fca826ae8f74bc97ef"}]$law7d0016$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
